PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY,name TEXT NOT NULL,hostname TEXT NOT NULL,platform TEXT NOT NULL,arch TEXT NOT NULL,ax_version TEXT NOT NULL,protocol_version INTEGER NOT NULL,capabilities_json TEXT NOT NULL,status TEXT NOT NULL,last_seen INTEGER NOT NULL,public_key TEXT UNIQUE,revoked_at INTEGER);
CREATE TABLE IF NOT EXISTS pairings(code_hash TEXT PRIMARY KEY,expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE TABLE IF NOT EXISTS crews(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at INTEGER NOT NULL DEFAULT(unixepoch()));
CREATE TABLE IF NOT EXISTS crew_members(id TEXT PRIMARY KEY,crew_id TEXT NOT NULL REFERENCES crews(id),name TEXT NOT NULL,role TEXT NOT NULL,device_id TEXT NOT NULL REFERENCES devices(id),cwd TEXT NOT NULL,provider TEXT,model TEXT,skills_json TEXT NOT NULL,mcp_servers_json TEXT NOT NULL,permission_profile TEXT NOT NULL,max_concurrency INTEGER NOT NULL CHECK(max_concurrency>0));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,crew_id TEXT NOT NULL REFERENCES crews(id),parent_id TEXT REFERENCES tasks(id),title TEXT NOT NULL,description TEXT NOT NULL,assigned_member TEXT NOT NULL REFERENCES crew_members(id),assigned_device TEXT NOT NULL REFERENCES devices(id),priority INTEGER NOT NULL,status TEXT NOT NULL,input_json TEXT NOT NULL,output_json TEXT,retry_count INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL DEFAULT(unixepoch()),started_at INTEGER,finished_at INTEGER);
CREATE TABLE IF NOT EXISTS task_dependencies(task_id TEXT NOT NULL REFERENCES tasks(id),depends_on_id TEXT NOT NULL REFERENCES tasks(id),PRIMARY KEY(task_id,depends_on_id),CHECK(task_id<>depends_on_id));
CREATE TABLE IF NOT EXISTS task_runs(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),attempt INTEGER NOT NULL,status TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER,error TEXT);
CREATE TABLE IF NOT EXISTS session_bindings(task_id TEXT PRIMARY KEY REFERENCES tasks(id),member_id TEXT NOT NULL REFERENCES crew_members(id),device_id TEXT NOT NULL REFERENCES devices(id),ax_session_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,timestamp INTEGER NOT NULL DEFAULT(unixepoch()),kind TEXT NOT NULL,crew_id TEXT,member_id TEXT,device_id TEXT,task_id TEXT,session_id TEXT,payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS automations(id TEXT PRIMARY KEY,name TEXT NOT NULL,message TEXT NOT NULL,schedule_kind TEXT NOT NULL,interval_minutes INTEGER NOT NULL DEFAULT 60,daily_time TEXT NOT NULL DEFAULT '09:00',weekdays TEXT NOT NULL DEFAULT '',utc_offset_minutes INTEGER NOT NULL DEFAULT 480,member_id TEXT REFERENCES crew_members(id),model TEXT,approval TEXT NOT NULL DEFAULT 'default',silent INTEGER NOT NULL DEFAULT 0,strict_schedule INTEGER NOT NULL DEFAULT 0,hide_from_chat INTEGER NOT NULL DEFAULT 0,lean_context INTEGER NOT NULL DEFAULT 0,folder TEXT,enabled INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL DEFAULT(unixepoch()),last_run_at INTEGER,next_run_at INTEGER,run_count INTEGER NOT NULL DEFAULT 0,last_status TEXT);
CREATE TABLE IF NOT EXISTS automation_runs(id TEXT PRIMARY KEY,automation_id TEXT NOT NULL REFERENCES automations(id),task_id TEXT,status TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER,detail TEXT);
CREATE INDEX IF NOT EXISTS idx_tasks_status ON tasks(status,priority DESC,created_at);
CREATE INDEX IF NOT EXISTS idx_events_task ON events(task_id,timestamp);
CREATE INDEX IF NOT EXISTS idx_automations_due ON automations(enabled,next_run_at);
CREATE TABLE IF NOT EXISTS client_pairings(code_hash TEXT PRIMARY KEY,expires_at INTEGER NOT NULL,used_at INTEGER,device_id TEXT,name TEXT,platform TEXT,status TEXT NOT NULL DEFAULT 'pending',credential_pending TEXT);
CREATE TABLE IF NOT EXISTS client_authorizations(device_id TEXT PRIMARY KEY,name TEXT NOT NULL,platform TEXT NOT NULL,credential_hash TEXT NOT NULL,created_at INTEGER NOT NULL,last_active INTEGER NOT NULL DEFAULT 0,revoked_at INTEGER);
CREATE TABLE IF NOT EXISTS app_settings(key TEXT PRIMARY KEY,value_json TEXT NOT NULL);
PRAGMA user_version=3;
